355	// GitHub hands labels back as objects on the issues API and as bare strings in
356	// some fixtures; accept either.
357	export const labelNames = (issue) =>
358	  (issue?.labels ?? []).map((l) => (typeof l === 'string' ? l : l?.name)).filter(Boolean);
359	
360	export const hasLabel = (issue, name) => labelNames(issue).includes(name);
361	
362	// Title. The optional qualifier exists ONLY for deliberately concurrent items —
363	// a fan-out naming its target — and it is part of the identity the same-title
364	// mutex reads (DESIGN §6.1). Nothing ever encodes a date here: that was the slot
365	// grammar, and the issue number is the identity (DESIGN §5).
366	export const workItemTitle = ({ pack, task, qualifier = null }) =>
367	  `${WORK_PREFIX} ${pack}/${task}${qualifier ? ` ${qualifier}` : ''}`;
368	
369	// pack and task ids are single path segments; the qualifier is whatever follows.
370	const TITLE_RE = /^\[claudinite-work\]\s+([^/\s]+)\/([^/\s]+)(?:\s+(\S.*))?$/;
371	
372	// The pack half is canonicalized on the way out. A work item's title is STORED
373	// DATA — it sits on an open GitHub issue that outlives any one converge — so items
374	// filed before a pack was renamed still carry the old spelling. Read literally, the
375	// scheduler run would not recognise its own live item, would file a second one beside it, and
376	// would leave the first orphaned in the queue with nothing ever draining it.
377	export function parseWorkItemTitle(title) {
378	  const m = TITLE_RE.exec(String(title ?? '').trim());
379	  return m ? { pack: canonicalPackId(m[1]), task: m[2], qualifier: m[3]?.trim() || null } : null;
380	}
381	
382	export const isWorkItemTitle = (title) => parseWorkItemTitle(title) !== null;
383	
384	// The `<pack>/<task>` id a WORKER PATH names — the identity half a marked issue's
385	// title cannot carry (DESIGN §16.1), read off the path its machine block names. Two
386	// shapes, because tasks have two homes: the `tasks/` slot a declared pack contributes,
387	// and the queue's own built-in root. The `.claudinite/shared/` prefix is optional in
388	// both — a member's mount is there and the canon runs its own tree.
389	//
390	// THE BUILT-IN ROOT HAS TWO SPELLINGS, and both are permanent. The surface moved from
391	// `engine/scheduler/` to the tasks pack (#1317), so a live item minted before the move
392	// still names the engine path while every new one names the pack path; the wire id
393	// either produces is unchanged, which is what the move promised. Stored data is
394	// renamed on the DECODE side or it stops decoding, and here that failure is silent:
395	// this is the fallback for a marked issue, whose title is the requester's own words,
396	// so a path that yields null leaves the item unattributable rather than rejected.
397	//
398	// It is a PARSE, not a lookup: anything that must know the task exists at HEAD
399	// resolves the path against the discovered task set instead (the executor does).
400	const PACK_TASK_PATH_RE = /^(?:\.claudinite\/shared\/)?packs\/([^/]+)\/tasks\/([^/]+)\/[^/]+$/;
401	const BUILT_IN_TASK_PATH_RE = /^(?:\.claudinite\/shared\/)?(?:engine\/scheduler|packs\/claudinite-tasks)\/queue\/tasks\/([^/]+)\/[^/]+$/;
402	
403	export function taskIdFromPath(path) {
404	  const p = String(path ?? '');
405	  const pack = PACK_TASK_PATH_RE.exec(p);
406	  if (pack) return { pack: canonicalPackId(pack[1]), task: pack[2] };
407	  const builtIn = BUILT_IN_TASK_PATH_RE.exec(p);
408	  return builtIn ? { pack: 'engine', task: builtIn[1] } : null;
409	}
410	
411	// STANDING OR AD-HOC, DERIVED (DESIGN §15.26). A task's standing item is the one
412	// the generator files at an anchor: its title names the task and nothing else, and
413	// the task it names is on a calendar. Everything else is ad-hoc — a `manual` task
414	// (which has no anchor to stand for) and every qualified item (a fan-out target, a
415	// request naming its issue), each of which may legitimately run beside the
416	// occurrence rather than being it.
417	//
418	// It is read off the item and the declaration at HEAD rather than off a label the
419	// creator applied, because the two could disagree: a marker says what its writer
420	// believed, the structure says what the item IS, and the guards that consume this
421	// (the occurrence guard, the dedupe, the `after` yield) are only sound on the
422	// second. `frequency` is the declared frequency of the task the title names —
423	// absent when the repo no longer carries it, which is ad-hoc by the same rule.
424	export function isStandingItem(item, frequency) {
425	  const parsed = parseWorkItemTitle(item?.title ?? item);
426	  return !!parsed && parsed.qualifier === null && frequency != null && frequency !== 'manual';
427	}
