429	// --- comment markers ----------------------------------------------------------
430	// The three comments the protocol reads back. They are HTML comments so a human
431	// reading the item sees prose, and they are here — with the labels and the body
432	// fields — because together they ARE the item's vocabulary, the one compatibility
433	// surface across engine versions (DESIGN §14).
434	//
435	// The CLAIM comment carries who and when (executor identity is an unbounded set
436	// and must never become a label). The HANDOFF comment names the session and the
437	// invocation nonce. The EPISODE comment is the boundary the claim arbiter is
438	// scoped to: every claim before it is dead, and arbitrating over dead claims makes
439	// one outrank every future live claimant — the item then livelocks through reclaim
440	// cycles forever (F18). A reclaim, a revert and a hand re-queue each write one.
441	export const CLAIM_MARKER = '<!-- claudinite-claim -->';
442	export const HANDOFF_MARKER = '<!-- claudinite-handoff -->';
443	export const EPISODE_MARKER = '<!-- claudinite-episode -->';
444	
445	// --- the body -----------------------------------------------------------------
446	
447	export const NOT_BEFORE_FIELD = 'Not-before';
448	export const BLOCKED_BY_FIELD = 'Blocked-by';
449	
450	// The three fields a REQUEST item carries (DESIGN §16.3, §16.11). `Request` is the issue this
451	// run implements — the whole payload, since the request task has no code-work phase
452	// to hand one over. `Model` is the family the asker chose, copied here by the scheduler run
453	// from a write-gated label and read only by a task that declares
454	// `model_from_request`; it is the first thing an item carries that defines
455	// behaviour, which is why it is fenced rather than waved through (§16.7).
456	export const REQUEST_FIELD = 'Request';
457	export const MODEL_FIELD = 'Model';
458	
459	// `Task` is the TARGETING field (DESIGN §16, the one-issue request): which task a
460	// marked issue asks for, as `<pack>/<task>`. Absent, the ask is the built-in
461	// request implementer, which is what an ordinary "implement this issue" mark means.
462	// It rides the same author gate as `Model` and `Merge`: naming a task is choosing
463	// what runs, and a body is editable by whoever opened the issue.
464	export const TASK_FIELD = 'Task';
465	
466	// `Merge` is the asker's standing authorization, copied here from the
467	// write-gated `claude-automerge` label. Its one value is `if-narrow`: the run may
468	// land its own pull request when the diff classifier calls the diff narrow, and
469	// must park for approval otherwise. An absent field is the default — never merge —
470	// so an item an older scheduler run wrote reads as unauthorized rather than as authorized.
471	export const MERGE_FIELD = 'Merge';
472	export const MERGE_IF_NARROW = 'if-narrow';
473	
474	// The heading the delivered-artifacts section carries in a work item body. One
475	// home, because it is written in three places and MATCHED when a re-entrant run
476	// updates the section it already wrote.
477	export const DELIVERED_HEADING = 'Delivered by code-work';
478	
479	// The same heading as earlier renames spelled it. A live item's body still carries
480	// whichever word was current when its section was first written, and matching only
481	// today's would append a SECOND section rather than updating that one.
482	export const LEGACY_DELIVERED_HEADINGS = Object.freeze([
483	  'Delivered by prework',
484	  'Delivered by code_work',
485	]);
486	
487	// --- the machine block (DESIGN §16.1, §16.3) ----------------------------------
488	// A one-issue request's item IS the issue somebody marked, so the item's fields
489	// share a body a person authored and keeps editing. They live in one delimited
490	// block, appended at adoption and rewritten in place after that: everything outside
491	// it belongs to the human, everything inside it to the machine, and a parser that
492	// read the whole body would take a sentence of prose for a field.
493	//
494	// A `[claudinite-work]` item has no block — its whole body is the machine's — so
495	// every reader here falls back to the whole text, which is what keeps items filed
496	// before the one-issue model draining unchanged.
497	export const MACHINE_BLOCK_START = '<!-- claudinite-item -->';
498	export const MACHINE_BLOCK_END = '<!-- /claudinite-item -->';
499	
500	const BLOCK_RE = /<!-- claudinite-item -->\n?([\s\S]*?)\n?<!-- \/claudinite-item -->/;
501	
502	// The machine's half of a body, or null where there is no block at all.
503	export const machineBlockOf = (body) => BLOCK_RE.exec(String(body ?? ''))?.[1] ?? null;
504	
505	// The machine's half to read fields out of: the block where there is one, the whole
506	// body otherwise.
507	export const itemFieldText = (body) => machineBlockOf(body) ?? String(body ?? '');
508	
509	// Replace the block, or append one to a body that has none. The human's text is
510	// never rewritten — an append lands after it, separated by a blank line.
511	export function withMachineBlock(body, block) {
512	  const text = String(body ?? '');
513	  const wrapped = `${MACHINE_BLOCK_START}\n${block.replace(/\s*$/, '')}\n${MACHINE_BLOCK_END}`;
514	  if (BLOCK_RE.test(text)) return text.replace(BLOCK_RE, wrapped);
515	  return `${text.replace(/\s*$/, '')}\n\n${wrapped}\n`;
516	}
517	
518	// Apply an edit to whichever half is the machine's. Every writer that reshapes an
519	// item body — a Context section, code-work's delivered list, a stamped
520	// `Not-before` — goes through here, so it edits the block on a marked issue and the
521	// whole body on a `[claudinite-work]` item, with one call site either way.
522	export function editItemBody(body, edit) {
523	  const block = machineBlockOf(body);
524	  return block === null ? edit(String(body ?? '')) : withMachineBlock(body, edit(block));
525	}
526	
527	// The human's half of a body — everything the machine block is not. A marked
528	// issue's PARAMETERS are read from here and never from the block: re-asking clears
529	// the status and leaves the previous run's block standing, and a parser that read
530	// the whole body would find that stale copy beside the person's own field.
531	export const humanTextOf = (body) => String(body ?? '').replace(BLOCK_RE, '').trim();
532	
533	const NOT_BEFORE_RE = /^Not-before:[ \t]*(.*)$/m;
534	const BLOCKED_BY_RE = /^Blocked-by:[ \t]*(.*)$/m;
535	const REQUEST_RE = /^Request:[ \t]*#?(\d+)/m;
536	const MODEL_RE = /^Model:[ \t]*(\S+)/m;
537	const MERGE_RE = /^Merge:[ \t]*(\S+)/m;
538	
539	// Build a work item body. The first line is the task path — the only thing an
540	// executor reads to locate the worker, validated in code before anything trusts
541	// it. Everything behavior-defining (model, ceiling, worker content, code-work
542	// command) is read from the tracked task files at HEAD, never from here.
543	export function workItemBody({
544	  taskPath, notBefore = null, blockedBy = [], context = [], delivered = [], reason = null,
545	  request = null, model = null, merge = null,
546	}) {
547	  const lines = [taskPath, ''];
548	  const fields = [];
549	  if (notBefore) fields.push(`${NOT_BEFORE_FIELD}: ${notBefore}`);
550	  if (blockedBy.length) fields.push(`${BLOCKED_BY_FIELD}: ${blockedBy.map((n) => `#${n}`).join(', ')}`);
551	  if (request) fields.push(`${REQUEST_FIELD}: #${request}`);
552	  if (model) fields.push(`${MODEL_FIELD}: ${model}`);
553	  if (merge) fields.push(`${MERGE_FIELD}: ${merge}`);
554	  if (fields.length) lines.push(...fields, '');
555	  lines.push('Execute the Claudinite task above.');
556	  if (context.length) {
557	    lines.push(
558	      'The Context section below is binding scope — do not re-decide it.',
559	      '',
560	      '### Context',
561	      ...context.map((c) => `- ${c}`),
562	    );
563	  }
564	  if (reason) lines.push('', '### Why the agent is here', '', `- ${reason}`);
565	  if (delivered.length) lines.push('', `### ${DELIVERED_HEADING}`, '', ...delivered.map((d) => `- ${d}`));
566	  return lines.join('\n') + '\n';
567	}
568	
569	// The `Blocked-by` numbers a body names, from a work item's body or from an
570	// ORDINARY issue's — a request marked for implementation states what it waits on in
571	// the same field spelling, and adoption carries it onto the item it births (§16.11).
572	export function parseBlockedBy(body) {
573	  const bb = BLOCKED_BY_RE.exec(String(body ?? ''))?.[1] ?? '';
574	  return [...bb.matchAll(/#(\d+)/g)].map((m) => Number(m[1]));
575	}
576	
577	// Parse an item body back into the facts the scheduler run and the executor read. A body
578	// with no first line, or whose fields are absent, yields nulls — absence is
579	// meaningful everywhere here and is never filled in with a default.
580	export function parseWorkItemBody(body) {
581	  const text = itemFieldText(body);
582	  const taskPath = text.split('\n').map((l) => l.trim()).find((l) => l !== '') ?? null;
583	  const nb = NOT_BEFORE_RE.exec(text)?.[1]?.trim() || null;
584	  const blockedBy = parseBlockedBy(text);
585	  const request = REQUEST_RE.exec(text) ? Number(REQUEST_RE.exec(text)[1]) : null;
586	  // An unrecognised family reads as absent rather than as itself: the item's model
587	  // is behaviour-defining, so the only values that leave this parser are ones the
588	  // engine can actually dispatch at (§16.7).
589	  const askedModel = MODEL_RE.exec(text)?.[1] ?? null;
590	  const model = REQUEST_MODELS.includes(askedModel) ? askedModel : null;
591	  // Same fencing as the model: an unrecognised authorization reads as absent, and
592	  // absent is the safe end of this field — a run that cannot read its permission
593	  // opens a pull request and waits.
594	  const askedMerge = MERGE_RE.exec(text)?.[1] ?? null;
595	  const merge = askedMerge === MERGE_IF_NARROW ? askedMerge : null;
596	  return { taskPath, notBefore: nb, blockedBy, request, model, merge };
597	}
598	
599	// WHAT A MARKED ISSUE ASKS FOR (DESIGN §16.3, §16.7, §16.11) — read from the
600	// person's own text at every adoption, so each ask names its parameters afresh and
601	// nothing stale outranks a new one.
602	//
603	// `gated` is whether the issue's AUTHOR holds push access. A body is editable by
604	// whoever opened the issue where a label was write-gated by the platform, so the
605	// three behaviour-defining fields are honoured only for an author who could have
606	// applied them as labels anyway; an ungated ask still runs, at the default task and
607	// model and with no authorization to land anything.
608	export function parseRequestFields(body, { gated = false } = {}) {
609	  const text = humanTextOf(body);
610	  const asked = {
611	    task: /^Task:[ \t]*(\S+)/m.exec(text)?.[1] ?? null,
612	    model: MODEL_RE.exec(text)?.[1] ?? null,
613	    automerge: /^Automerge:[ \t]*(\S+)/m.exec(text)?.[1]?.toLowerCase() ?? null,
614	  };
615	  const blockedBy = parseBlockedBy(text);
616	  const notBefore = NOT_BEFORE_RE.exec(text)?.[1]?.trim() || null;
617	  if (!gated) return { task: null, model: null, merge: null, blockedBy, notBefore, ungated: Object.values(asked).some(Boolean) };
618	  return {
619	    task: /^[^/\s]+\/[^/\s]+$/.test(asked.task ?? '') ? asked.task : null,
620	    // An unrecognised family reads as absent rather than failing the request: a run
621	    // nobody can start would look accepted forever.
622	    model: REQUEST_MODELS.includes(asked.model) ? asked.model : null,
623	    merge: ['if-narrow', 'yes', 'true'].includes(asked.automerge) ? MERGE_IF_NARROW : null,
624	    blockedBy,
625	    notBefore,
626	    ungated: false,
627	  };
628	}
629	
630	// The item's own `### Context` bullets, in order — the binding scope a hand-created
631	// item was born with. Read back rather than kept only for the agent to read,
632	// because an operator's PARAMETERS ride here: `create-work-item --context
633	// "REPOS=Alpha Beta"` is how a forced run says what it is running on, and the
634	// executor hands these lines to code-work as `CLAUDINITE_CONTEXT`.
635	//
636	// A section runs to the next `### ` heading or to the end of the body — the same
637	// bounds `withSection` writes to — and only `- ` bullets count, so the prose
638	// framing around a section contributes nothing.
639	function sectionLines(body, heading) {
640	  const lines = String(body ?? '').split('\n');
641	  const at = lines.findIndex((l) => l.trim() === `### ${heading}`);
642	  if (at === -1) return [];
643	  const out = [];
644	  for (const line of lines.slice(at + 1)) {
645	    if (line.startsWith('### ')) break;
646	    const m = /^-[ \t]+(.*)$/.exec(line);
647	    if (m) out.push(m[1].trim());
648	  }
649	  return out;
650	}
651	
652	export const parseContextLines = (body) => sectionLines(body, 'Context');
653	
654	// --- the roll's record ----------------------------------------------------------
655	
656	// The section a no-go roll keeps on the item: the last declined reason and the next
657	// wake, REPLACED on every roll (the item is a status line, not a log — the timeline
658	// carries the history). Serializer and parser live together so the shape has one
659	// home; the executor writes it, and anything answering "why didn't it run" — the
660	// dashboard above all — reads it back.
661	export const LAST_VERDICT_HEADING = 'Last verdict';
662	
663	export function lastVerdictLines({ at, reason, until }) {
664	  const lines = [`${at} — the precondition declined: ${reason}`];
665	  if (until) lines.push(`Asked again at ${until}.`);
666	  return lines;
667	}
668	
669	export function parseLastVerdict(body) {
670	  const lines = sectionLines(body, LAST_VERDICT_HEADING);
671	  // The reason may carry the separator itself, so the split is on the FIRST match.
672	  const first = /^(.*?) — the precondition declined: ([\s\S]*)$/.exec(lines[0] ?? '');
673	  if (!first) return null;
674	  const until = lines.map((l) => /^Asked again at (.*?)\.?$/.exec(l)).find(Boolean)?.[1] ?? null;
675	  return { at: first[1], reason: first[2], until };
676	}
677	
678	// Fold a second set of Context lines into the first, keeping order and dropping
679	// exact duplicates. Both sides are real scope — the item carries what its creator
680	// bound it to, the precondition adds what this occurrence found — and a set-write
681	// from either side would drop the other's.
682	export const mergeContext = (...groups) => [...new Set(groups.flat().filter((l) => l && l.trim()))];
683	
684	// Stamp (or clear) `Not-before` on an existing body, in place where the field is
685	// already present and directly under the task path otherwise. Text surgery rather
686	// than a rebuild: the body also carries the creating precondition's Context and
687	// code-work's Delivered section, which belong to whoever wrote them.
688	export function withNotBefore(body, iso) {
689	  const text = String(body ?? '');
690	  if (NOT_BEFORE_RE.test(text)) {
691	    return iso
692	      ? text.replace(NOT_BEFORE_RE, `${NOT_BEFORE_FIELD}: ${iso}`)
693	      : text.replace(/^Not-before:[ \t]*.*\n?/m, '');
694	  }
695	  if (!iso) return text;
696	  const lines = text.split('\n');
697	  const at = lines.findIndex((l) => l.trim() !== '');
698	  if (at === -1) return `${NOT_BEFORE_FIELD}: ${iso}\n`;
699	  lines.splice(at + 1, 0, '', `${NOT_BEFORE_FIELD}: ${iso}`);
700	  return lines.join('\n');
701	}
702	
703	// Set a section of an item body (the Context, code-work's Delivered, the agent's Why)
704	// — replacing one of the same heading if it is already there, appending otherwise.
705	//
706	// REPLACING IS THE WHOLE POINT, and appending was a live bug (#879). Every standing
707	// item is born carrying a `### Context`, and the hand-off writes Context again — so
708	// an append leaves TWO sections of that name, while the session is told to read "the
709	// issue's Context section", singular. The one it reads first is then the scheduler run's birth
710	// note and the binding scope is in the other, which fails silently whichever section
711	// the agent picks. It also grows: an item re-queued through hand-off twice carried a
712	// third.
713	//
714	// A section runs to the next `### ` heading or to the end of the body, so a replaced
715	// section keeps its position rather than migrating to the bottom — the body stays in
716	// the order a reader learned it.
717	// `aliases` are older spellings of the SAME heading. The section is rewritten under
718	// `heading`, but located by any of them, so a body written before a rename is updated
719	// in place instead of gaining a second section.
720	export function withSection(body, heading, lines, aliases = []) {
721	  if (!lines.length) return body;
722	  const text = String(body ?? '').replace(/\s*$/, '');
723	  const section = [`### ${heading}`, '', ...lines.map((l) => `- ${l}`)];
724	  const existing = text.split('\n');
725	  const wanted = new Set([heading, ...aliases].map((h) => `### ${h}`));
726	  const at = existing.findIndex((l) => wanted.has(l.trim()));
727	  if (at === -1) return `${text}\n\n${section.join('\n')}\n`;
728	  const after = existing.findIndex((l, i) => i > at && l.startsWith('### '));
729	  const tail = after === -1 ? [] : ['', ...existing.slice(after)];
730	  return `${[...existing.slice(0, at), ...section, ...tail].join('\n')}\n`;
731	}
732

